33	\section{The problem}
34	
35	Let $f\colon S^2\to S^2$ be a branched cover, $V(f)$ the set of its critical values, and $A,B\subset S^2$ finite sets.
36	\begin{enumerate}
37	\item If $f(A)\cup V(f)\subset B$, then every complex structure on $(S^2,B)$ can be pulled back to a complex structure on $(S^2,A)$, and this induces the map $f^*\colon\Teich(B)\to\Teich(A)$.
38	\item If $A\subset B$, then forgetting the points $B\setminus A$ induces the map $i_*\colon\Teich(B)\to\Teich(A)$.
39	\end{enumerate}
40	If $f(A)\cup V(f)\cup A\subset B$, then the \emph{deformation space} is defined by
41	\[\D_f:=\{\tau\in\Teich(B): f^*(\tau)=i_*(\tau)\}.\]
42	Consider a quadratic rational map $f$ with critical points $c_1$ and $c_2$. Assume that $c_1$ belongs to a cycle of length $4$, and the critical value $v=f(c_2)$ does not belong to the cycle. By taking
43	\[A=\{c_1,f(c_1),f^{\circ2}(c_1),f^{\circ3}(c_1)\},\qquad B=A\cup\{v\},\]
44	we get a deformation space $\D_f\subset\Teich(B)$. Its image in the moduli space is the set of conjugacy classes of quadratic rational maps with the properties described above.
45	
46	\emph{Explicitly describe a simple closed curve $\gamma\subset(S^2,B)$ such that a power of the Dehn twist around this curve preserves the deformation space, and its action on the set of connected components of $\D_f$ has an infinite orbit.}
47	
48	\section{The result}
49	
50	Throughout, $f$ is as in the problem, $a_i=f^{i}(c_1)$ (indices mod $4$), so $A=\{a_0,a_1,a_2,a_3\}$ and $B=A\cup\{v\}$. The critical values of $f$ are $a_1=f(c_1)$ and $v$. For an essential simple closed curve $\gamma\subset S^2\setminus B$ we write $T_\gamma$ for the Dehn twist about $\gamma$, an element of the pure mapping class group $\PMod(S^2,B)$, which acts on $\Teich(B)$ (see \S\ref{sec:teich}).
51	
52	\begin{theorem}\label{thm:main}
53	\textbf{(a) Model case.} Let
54	\[f=f_{1/4}(z)=1-\frac{11}{12z}+\frac1{6z^2}.\]
55	Its $4$-cycle is $c_1=0\mapsto\infty\mapsto1\mapsto\tfrac14\mapsto0$, its second critical point is $c_2=4/11$, and $v=-25/96$. On $\Rh$ the points of $B$ are ordered as
56	\[v<c_1=0<f^{3}(c_1)=\tfrac14<f^{2}(c_1)=1<f(c_1)=\infty .\]
57	Let $\alpha$ be a simple arc from $v$ to $f(c_1)=\infty$ with the following crossing pattern with $\Rh$:
58	\begin{enumerate}[label=\textup{(\arabic*)}]
59	\item it leaves $v$ into the lower half-plane and crosses $\mathbb R$ upward at a point $x_1\in(1,\infty)$;
60	\item it runs in the upper half-plane and crosses $\mathbb R$ downward at a point $x_2\in(0,\tfrac14)$;
61	\item it runs in the lower half-plane and crosses $\mathbb R$ upward at a point $x_3\in(v,0)$;
62	\item it stays in the upper half-plane until $\infty$.
63	\end{enumerate}
64	Thus $\alpha$ meets $\Rh$ only at $v,x_1,x_2,x_3,\infty$, crossing transversally at $x_1,x_2,x_3$. A concrete choice is: the lower semicircle from $v$ to $2$; then the upper semicircle over $[\tfrac18,2]$; then the lower semicircle over $[-\tfrac18,\tfrac18]$; then the vertical ray from $-\tfrac18$ up to $\infty$.
65	
66	Let $\gamma=\partial N(\alpha)$ be the boundary of a thin closed regular neighbourhood of $\alpha$. Then $\gamma$ is a simple closed curve in $S^2\setminus B$; it bounds a disc containing exactly $v$ and $f(c_1)$, and the complementary disc contains $c_1,f^2(c_1),f^3(c_1)$. The Dehn twist $T_\gamma$ itself (power $1$) satisfies
67	\[f^*\circ T_\gamma=f^*\qquad\text{and}\qquad i_*\circ T_\gamma=i_*,\]
68	so $T_\gamma(\D_f)=\D_f$. For every connected component $D_0$ of $\D_f$ and every $m\ne0$ we have $T_\gamma^m(D_0)\ne D_0$. Hence every orbit of $\langle T_\gamma\rangle$ on $\pi_0(\D_f)$ is infinite; in particular $\D_f$ has infinitely many components.
69	
70	\smallskip
71	\textbf{(b) Every $f$.} Let $f$ be arbitrary as in the problem. By Proposition~\ref{prop:normal} there are a unique $t\in W$ and a unique M\"obius map $M$ with $M\circ f\circ M^{-1}=f_t$ and $M(c_1)=0$. Choose a path $t_s$ in $W$ from $\tfrac14$ to $t$ and let $h_1$ be the endpoint of an isotopy following the marked points (Lemma~\ref{lem:isotopy}). Then the curve
72	\[\gamma_f:=M^{-1}(h_1(\gamma))\]
73	has the same property for $f$: $T_{\gamma_f}$ preserves $\D_f$, and every orbit of $\langle T_{\gamma_f}\rangle$ on $\pi_0(\D_f)$ is infinite.
74	
75	When $t\in\bigl(0,\tfrac{3-\sqrt5}{2}\bigr)$ this is explicit. The five points of $B$ lie on the circle $C=M^{-1}(\Rh)$ in the cyclic order $v,\,c_1,\,f^3(c_1),\,f^2(c_1),\,f(c_1)$. Call the \emph{upper} side of $C$ the image under $M^{-1}$ of the upper half-plane. Then $\gamma_f=\partial N(\alpha_f)$, where $\alpha_f$ is an arc from $v$ to $f(c_1)$ which
76	\begin{itemize}[nosep]
77	\item leaves $v$ into the lower side and crosses $C$ between $f^2(c_1)$ and $f(c_1)$;
78	\item crosses back between $c_1$ and $f^3(c_1)$;
79	\item crosses again between $v$ and $c_1$;
80	\item then runs on the upper side to $f(c_1)$.
81	\end{itemize}
82	\end{theorem}
83	
84	\paragraph{What is known and what is proved here.} The setting of the problem, and the disconnectedness of $\D_f$ for quadratic maps with a $4$-periodic critical point, go back to E.~Hironaka and S.~Koch~\cite{HK}; for background on the pullback map in this generality see \cite{DH,BEKP}. The argument below is self-contained apart from the classical facts (F1)--(F5) listed in \S\ref{sec:teich}, which are quoted with references and not reproved. Everything else (the normal form, the fibre formula, the obstruction $(\star)$, the linking criterion, the face analysis at $t=\tfrac14$, the isotopy and lifting lemmas) is proved here.
85	
86	\section{Overview of the proof}
87	
88	After a M\"obius change of coordinates every $f$ is one of the maps $f_t(z)=1+b/z+c/z^2$ with cycle $0\to\infty\to1\to t\to0$, where $t$ ranges over a connected set $W$, the complement of nine points in $\mathbb C$. The space $\Teich(A)$ is the upper half-plane $\HH$, with the modular function $\lambda$ as the universal covering of the moduli space $\mathbb C\setminus\{0,1\}$, so the pair $\Psi=(i_*,f^*)$ maps $\Teich(B)$ to $\HH\times\HH$ and $\D_f=\Psi^{-1}(\text{diagonal})$.
89	
90	The key algebraic fact is an explicit formula: if a point of $\Teich(B)$ has normalised coordinates $(0,\infty,1,t,v')$, then $w=\lambda(f^*\tau')$ satisfies $V_t(w)=v'$ for an explicit degree-$4$ rational function $V_t$. Since the fifth point $v'$ is never $\infty$, the value $w=1-t$ is never attained. Hence $\Psi(\Teich(B))$ avoids the graphs of all elements $g\in\Gamma(2)S$, where $S(\tau)=-1/\tau$; we call this the obstruction~$(\star)$. If $g$ has no fixed point in $\HH$, the complement $X_g$ of the graph of $g$ in $\HH\times\HH$ contains the diagonal and has $H_1(X_g)\cong\mathbb Z$, measured by winding about the graph. A mapping class $T$ with $\Psi\circ T=\Psi$ preserves $\D_f$. If, moreover, a path from $\tau$ to $T^m\tau$ has $\Psi$-image with nonzero class in $H_1(X_g)$, then $\tau$ and $T^m\tau$ cannot lie in the same component of $\D_f$, because a path inside $\D_f$ maps into the contractible diagonal. This is the linking criterion.
91	
92	For $f_{1/4}$ we take $\gamma$ around the two critical values $v$ and $a_1$, along the arc $\alpha$. Then $T_\gamma$ is a point push of $v$, so $i_*\circ T_\gamma=i_*$, and its lift through $f$ is computed from the lift of $\alpha$ through $V_{1/4}$. The map $V_{1/4}$ is Galois with Klein four deck group, and its real locus consists of $\Rh$ and two circles; a face-by-face analysis shows that the lift $\beta$ of $\alpha$ starting at $w=\tfrac14$ ends at $\tfrac34$ after winding once clockwise around $0$. Lifting through $\lambda$ yields the element $g=T^{-2}S$, which is parabolic and so has no fixed point. From this we get $f^*\circ T_\gamma=f^*$, and the $\Psi$-image of the fibre path from $\tau_0$ to $T_\gamma^m\tau_0$ winds $\pm m$ times about the graph of $g$, which proves (a). Part (b) follows by transporting $\gamma$ along an isotopy that follows the marked points as $t$ moves in $W$, which conjugates all the structures involved.
93	
94	\section{Normal form}\label{sec:normal}
95	
96	\begin{proposition}\label{prop:normal}
97	Put $f_t(z)=1+\dfrac bz+\dfrac c{z^2}$, with $b=\dfrac{t^2+t-1}{1-t}$ and $c=\dfrac{t(1-2t)}{1-t}$. Let $E$ be the set of $9$ points
98	\[E=\{0,1,\tfrac12\}\cup\{t:t^2-3t+1=0\}\cup\{t:t^2+t-1=0\}\cup\{t:3t^2-3t+1=0\},\]
99	and put $W=\mathbb C\setminus E$. For $f$ as in the problem there is exactly one pair $(t,M)$ with $t\in W$, $M$ M\"obius, $MfM^{-1}=f_t$ and $M(c_1)=0$. Conversely, for every $t\in W$ the map $f_t$ is as in the problem, with cycle $0\to\infty\to1\to t\to0$. Finally, $W$ is connected.
100	\end{proposition}
101	
102	\begin{proof}
103	\emph{Existence.} Let $M$ be the M\"obius map with $M(a_0,a_1,a_2)=(0,\infty,1)$, put $t=M(a_3)$ and $g=MfM^{-1}$. Then $0$ is a critical point of $g$ with $g(0)=\infty$, so $0$ is a double pole and the only pole; hence $g=P(z)/z^2$ with $\deg P\le2$ and $P(0)\ne0$. Since $g(\infty)=1$, we get $g=1+b/z+c/z^2$ with $c\ne0$. The conditions $g(1)=t$ and $g(t)=0$ read $1+b+c=t$ and $t^2+bt+c=0$. Substituting $c=t-1-b$ into the second gives $b(t-1)=1-t-t^2$. Hence $b$ and $c$ are as stated. (As checks, $b+c=t-1$ and $(1-t)(t^2+bt+c)=0$ identically.)
104	
105	\emph{Uniqueness.} Any other such $M'$ maps $c_1=a_0$ to $0$, and then $a_1,a_2$ to $f_{t'}(0)=\infty$ and $f_{t'}(\infty)=1$; so $M'(a_0,a_1,a_2)=(0,\infty,1)$ and $M'=M$.
106	
107	\emph{Which $t$ occur.} The value $t=\tfrac12$ gives $c=0$, and the degree drops. For $t\notin\{0,1,\tfrac12\}$ the map $f_t$ has degree $2$ and $0$ is a critical point of exact period $4$, since $0,\infty,1,t$ are distinct. Since $f_t'(z)=-(bz+2c)/z^3$, we have $c_2=-2c/b$, or $c_2=\infty=a_1$ if $b=0$, i.e.\ if $t^2+t-1=0$. Otherwise
108	\[v(t)=1-\frac{b^2}{4c}=-\frac{(t^2-3t+1)^2}{4t(1-t)(1-2t)},\]
109	using $(t^2+t-1)^2-(t^2-3t+1)^2=4t(1-t)(1-2t)$. Similarly, with $D=4t(1-t)(1-2t)$, one has $v-1=-(t^2+t-1)^2/D$ and $v-t=-(3t^2-3t+1)^2/D$; the latter because
110	\[(t^2-3t+1)^2+t\,D=9t^4-18t^3+15t^2-6t+1=(3t^2-3t+1)^2.\]
111	Hence $v=0\iff t^2-3t+1=0$, $v=1\iff b=0$, and $v=t\iff 3t^2-3t+1=0$. So $W$ is exactly the set of admissible parameters. It is $\mathbb C$ minus finitely many points, hence connected.
112	\end{proof}
113	
114	At $t=\tfrac14$ one gets $b=-\tfrac{11}{12}$, $c=\tfrac16$, $c_2=\tfrac4{11}$ and $v=-\tfrac{25}{96}$, which gives the map $f_{1/4}$ of Theorem~\ref{thm:main}(a).
115	
116	\paragraph{Factorisation.} Put $N_t(z)=z/(z-c_2(t))$ and $M_t(y)=v(t)+(1-v(t))/y$. Then
117	\begin{equation}\label{eq:factor}
118	f_t(z)=v+(1-v)\Bigl(1-\frac{c_2}{z}\Bigr)^2=M_t\bigl(N_t(z)^2\bigr).
119	\end{equation}
120	To check it, compare coefficients: $-2(1-v)c_2=b$ and $(1-v)c_2^2=c$, which follow from $1-v=b^2/(4c)$ and $c_2=-2c/b$. Both $M_t$ and $N_t$ depend continuously on $t\in W$. Also $N_t(0)=0$, $N_t(c_2)=\infty$, $M_t(0)=\infty$ and $M_t(\infty)=v$.
121	
122	\section{Teichm\"uller preliminaries}\label{sec:teich}
123	
124	\paragraph{Conventions.} A marking of $(S^2,X)$, with $|X|\ge3$, is an orientation-preserving homeomorphism $\varphi\colon S^2\to\Ch$. $\Teich(X)$ is the set of markings modulo the relation $\varphi_1\sim\varphi_2$, which holds iff there is a M\"obius map $M$ with $M\varphi_1=\varphi_2$ on $X$ and $M\varphi_1\simeq\varphi_2$ rel $X$. The pure mapping class group $\PMod(S^2,X)$ acts by $g\cdot[\varphi]=[\varphi g^{-1}]$; for a mapping class $T$ we write $F\circ T$ for the map $\tau\mapsto F(T\cdot\tau)$. The pullback $f^*[\varphi]=[\psi]$ is defined by requiring $\varphi\circ f\circ\psi^{-1}$ to be rational. In our situation $S^2=\Ch$, and $\tau_0=[\mathrm{id}]$ denotes the base point.
125	
126	\paragraph{Standard facts quoted, not reproved.}
127	\begin{enumerate}[label=\textbf{(F\arabic*)},leftmargin=*]
128	\item \label{F1} (Modular function; classical, see e.g.\ \cite{Ahlfors,Chandra}.) Let $\lambda=(\theta_2/\theta_3)^4\colon\HH\to\mathbb C\setminus\{0,1\}$. It is a holomorphic universal covering whose fibres are the orbits of $\Gamma(2)$. Moreover $\lambda(\tau+2)=\lambda(\tau)$ and $\lambda(-1/\tau)=1-\lambda(\tau)$; $\lambda(\tau)=16e^{i\pi\tau}+O(e^{2\pi i\tau})$ as $\Img\tau\to\infty$; and $y\mapsto\lambda(iy)$ is a decreasing bijection $(0,\infty)\to(0,1)$.
129	\item \label{F2} (Teichm\"uller; see e.g.\ \cite{Hubbard}.) $\Teich(X)$ is a complex manifold homeomorphic to $\mathbb R^{2(|X|-3)}$; in particular it is contractible. $\PMod(S^2,X)$ acts properly discontinuously by biholomorphisms, and the quotient is the moduli space $\M_{0,X}$.
130	\item \label{F3} (Bers fibration and Birman exact sequence \cite{Bers,Birman,FM}.) The forgetful map $i_*\colon\Teich(B)\to\Teich(A)$ is surjective. Fix $p\in\Teich(A)$ and normalise $a_0,a_1,a_2,a_3$ to $0,\infty,1,t$; write $A_p=\{0,\infty,1,t\}$. Recording the position $v'$ of the fifth point identifies the fibre $i_*^{-1}(p)$ with the universal cover of $\Ch\setminus A_p$. The point-push subgroup $\ker\bigl(\PMod(S^2,B)\to\PMod(S^2,A)\bigr)\cong\pi_1(S^2\setminus A,v)$, $[\ell]\mapsto\Push(\ell)$, acts on each fibre as the deck group: for the fibre through $\tau_0$, $\Push(\ell)^{\pm1}\cdot\tau_0$ is the endpoint of the lift through $v'$ of $\ell$ starting at $\tau_0$, the sign depending only on conventions.
131	\item \label{F4} (Push formula, see \cite{FM}.) The push of $v$ along a simple loop $\delta$ is $T_{\delta_L}T_{\delta_R}^{-1}$, where $\delta_L,\delta_R$ are the two boundary curves of a regular neighbourhood of $\delta$.
132	\item \label{F5} (Douady--Hubbard \cite{DH}.) $f^*$ is well defined and continuous; indeed it is holomorphic. (In \cite{DH} this is proved for Thurston's pullback map; the proof applies verbatim to $f^*\colon\Teich(B)\to\Teich(A)$.)
133	\end{enumerate}
134	The push formula is used only up to sign, and every argument below is symmetric under $m\mapsto-m$.
135	
136	\begin{lemma}[free action]\label{lem:free}
137	$\PMod(S^2,X)$ acts freely on $\Teich(X)$.
138	\end{lemma}
139	
140	\begin{proof}
141	Suppose $[\varphi g^{-1}]=[\varphi]$. Then $M\varphi=\varphi g^{-1}$ on $X$ for some M\"obius $M$. Since $g$ fixes $X$ pointwise, $M$ fixes the at least three points of $\varphi(X)$, so $M=\mathrm{id}$. Then $\varphi g^{-1}\simeq\varphi$ rel $X$, so $g=1$ in $\PMod(S^2,X)$.
142	\end{proof}
143	
144	By \ref{F2} and Lemma~\ref{lem:free}, the modulus map $\mathrm{mod}\colon\Teich(A)\to\mathbb C\setminus\{0,1\}$ is a covering, and since $\Teich(A)$ is simply connected it is a universal covering. It sends $[\varphi]$ to the $t$ for which some M\"obius map takes $\varphi(a_0,a_1,a_2,a_3)$ to $(0,\infty,1,t)$. By \ref{F1} there is a biholomorphism $\Theta\colon\Teich(A)\to\HH$ with $\lambda\circ\Theta=\mathrm{mod}$, and we use it to identify $\Teich(A)$ with $\HH$. For $f=f_{1/4}$ the base point $\tau_0=[\mathrm{id}]\in\Teich(B)$ lies in $\D_f$, because $f^*[\mathrm{id}]=[\mathrm{id}]$, $f$ being rational. Composing $\Theta$ with an element of $\Gamma(2)$ we normalise it so that $i_*\tau_0=p_0:=iy_0$, where $\lambda(iy_0)=\tfrac14$ (numerically $y_0\approx1.2793$).
145	
146	Put $\Psi=(i_*,f^*)\colon\Teich(B)\to\HH\times\HH$. Then $\D_f=\Psi^{-1}(\Delta)$, where $\Delta$ is the diagonal.
147	
148	\begin{lemma}[equivariance for a lift fixing $A$]\label{lem:equiv}
149	Let $\varphi$ be a homeomorphism fixing $B$ pointwise, and $\tilde\varphi$ a homeomorphism fixing $A$ pointwise with $f\tilde\varphi=\varphi f$. Then $f^*(\varphi\cdot\tau)=\tilde\varphi\cdot f^*(\tau)$.
150	\end{lemma}
151	
152	\begin{proof}
153	Let $\tau=[\psi_0]$ and suppose $\psi_0 f=F\psi$ with $F$ rational. Then $\psi_0\varphi^{-1}f=\psi_0 f\tilde\varphi^{-1}=F(\psi\tilde\varphi^{-1})$, so $f^*[\psi_0\varphi^{-1}]=[\psi\tilde\varphi^{-1}]$.
154	\end{proof}
155	
156	A lift of an element of $\PMod(S^2,B)$ need not fix $A$ pointwise: it may exchange $a_i$ with the other preimage of $a_{i+1}$. So Lemma~\ref{lem:equiv} has to be applied to an explicitly constructed lift, as in the next lemma.
157	
158	\begin{lemma}[lift of $T_\gamma$]\label{lem:lift}
159	Let $\alpha$ be a simple arc from $v$ to $a_1$ with interior in $S^2\setminus B$. Let $\gamma=\partial N(\alpha)$, and realise $T_\gamma$ in a collar $R\subset S^2\setminus N(\alpha)$ disjoint from $B$. Then:
160	\begin{enumerate}[label=\textup{(\roman*)},nosep]
161	\item $f^{-1}(R)=R_1\sqcup R_2$, with each $R_j$ mapped homeomorphically onto $R$;
162	\item the map $\tilde T$ defined as $(f|_{R_j})^{-1}\,T_\gamma\, f$ on $R_j$ and the identity elsewhere is a homeomorphism with $f\tilde T=T_\gamma f$;
163	\item $\tilde T$ fixes $f^{-1}(B)\supset A$ pointwise.
164	\end{enumerate}
165	Hence $f^*\circ T_\gamma=[\tilde T]\cdot f^*$ with $[\tilde T]\in\PMod(S^2,A)$.
166	\end{lemma}
167	
168	\begin{proof}
169	$R$ contains no critical value, so $f^{-1}(R)\to R$ is a $2$-sheeted covering. Its monodromy around the core of $R$ is the product of the monodromies around the two critical values $v,a_1$ inside $\gamma$. Each of these is the transposition of the two sheets, so the product is trivial. Hence the covering splits into two annuli, each mapped homeomorphically. Since $T_\gamma=\mathrm{id}$ on $\partial R$, $\tilde T$ is continuous and bijective, hence a homeomorphism of $S^2$, and $f\tilde T=T_\gamma f$ holds on each $R_j$ and trivially elsewhere. The set $f^{-1}(B)$ is disjoint from $f^{-1}(R)$, so $\tilde T$ fixes it; it contains $A$ because $f(A)=A\subset B$. Lemma~\ref{lem:equiv} gives the last statement.
170	\end{proof}
171	
172	\section{The fibre formula and the obstruction \texorpdfstring{$(\star)$}{(*)}}
173	
174	\begin{lemma}\label{lem:fibreformula}
175	Let $\tau'\in\Teich(B)$ be represented, after normalising, by
176	\[(\Ch;a_0,a_1,a_2,a_3,v)=(0,\infty,1,t,v').\] Then $w:=\lambda(f^*\tau')$ satisfies
177	\[V_t(w)=v',\qquad\text{where}\quad V_t(w)=-\frac{\bigl((w-1)^2-t\bigr)^2}{4w(w-1)(w+t-1)} .\]
178	\end{lemma}
179	
180	\begin{proof}
181	The pulled-back structure carries a degree-$2$ rational map $F$ whose critical values are the images $\infty$ and $v'$ of the critical values $a_1$ and $v$. Up to a M\"obius change in the source, $F(z)=v'+z^2$. Since $a_0=c_1$ is the critical point over $a_1$, its marked image is $a_0'=\infty$. The other points satisfy $F(a_i')=$ (image of $a_{i+1}$), so $a_1'=s_2$, $a_2'=s_3$, $a_3'=s_0$ with
182	\[s_2^2=1-v',\qquad s_3^2=t-v',\qquad s_0^2=-v';\]
183	the marking determines the signs. The map $z\mapsto(s_3-s_2)/(z-s_2)$ sends $(\infty,s_2,s_3,s_0)$ to $(0,\infty,1,w)$, so $w=(s_3-s_2)/(s_0-s_2)$.
184	
185	Put $u=s_2-s_0$ and $U=u^2$. From $s_2^2-s_0^2=1$ we get $s_2+s_0=u^{-1}$, so $s_2=(u+u^{-1})/2$ and $s_0=(u^{-1}-u)/2$. Also $s_3=s_2-wu$. The relation $s_3^2-s_0^2=t$ becomes $1-w(U+1)+w^2U=t$, so
186	\[U=\frac{w+t-1}{w(w-1)},\qquad 1-U=\frac{(w-1)^2-t}{w(w-1)}.\]
187	Then $v'=-s_0^2=-(1-U)^2/(4U)$, which is the stated formula.
188	\end{proof}
189	
190	Note that $V_t(t)=-\dfrac{(t^2-3t+1)^2}{4t(t-1)(2t-1)}=v(t)$.
191	
192	\begin{corollary}[the obstruction $(\star)$]\label{cor:star}
193	$V_t^{-1}(\infty)=\{0,1,\infty,1-t\}$, and at $w=1-t$ the numerator of $V_t$ equals $(t^2-t)^2\ne0$. Since $v'\ne a_1=\infty$, we get $w\ne1-t$. Thus
194	\[\lambda(f^*\tau')\ne1-\lambda(i_*\tau')\qquad\text{for all }\tau'\in\Teich(B). \tag{$\star$}\]
195	By \ref{F1}, $\lambda(q)=1-\lambda(p)=\lambda(-1/p)$ holds iff $q=g(p)$ for some $g\in\Gamma(2)S$, where $S(\tau)=-1/\tau$. So $\Psi(\Teich(B))$ avoids every graph $\Gamma_g=\{(p,g(p)):p\in\HH\}$ with $g\in\Gamma(2)S$.
196	\end{corollary}
197	
198	\begin{proof}
199	The denominator vanishes at $0,1,1-t$, which are distinct since $t\ne0,1$, and the numerator is $(1-t)^2$, $t^2$, $(t^2-t)^2$ there, all nonzero. Since the numerator has degree $4$ and the denominator degree $3$, also $V_t(\infty)=\infty$. The rest was explained in the statement, using $\lambda(i_*\tau')=t$.
200	\end{proof}
201	
202	\begin{lemma}[branching of $V_t$]\label{lem:branch}
203	For $t\in W$, $V_t$ has degree $4$ and is unbranched over $\Ch\setminus\{0,1,t\}$.
204	\end{lemma}
205	
206	\begin{proof}
207	By the proof of Corollary~\ref{cor:star}, numerator and denominator are coprime, so $\deg V_t=4$. Fix $v'\notin\{0,1,t,\infty\}$. If $V_t(w)=v'$, then $w\notin\{0,1,1-t,\infty\}$; reversing the computation in the proof of Lemma~\ref{lem:fibreformula} (choose $u$ with $u^2=U$ and define $s_2,s_0,s_3$ by the formulas there) shows that $w=(s_3-s_2)/(s_0-s_2)$ for some choice of square roots $s_2,s_3,s_0$ of $1-v',t-v',-v'$. So the solutions $w$ come from the sign choices of $(s_2,s_3,s_0)$ modulo a global sign, and there are at most $4$ of them.
208	
209	They are distinct. If two sign classes gave the same $w$, the M\"obius map carrying one quadruple $(\infty,s_2,s_3,s_0)$ to the other would be an affine map $L$ with $L(s_j)=\pm s_j$, with a sign pattern that is not constant. Then $L(z)^2-z^2$, of degree at most $2$, would vanish at the three distinct points $s_2,s_3,s_0$, forcing $L=\pm\mathrm{id}$, a contradiction. Over $\infty$ there are $4$ simple preimages $0,1,1-t,\infty$. Hence every point outside $\{0,1,t\}$ has $4$ distinct preimages.
210	\end{proof}
211	
212	\begin{lemma}[fibre lemma]\label{lem:fibre}
213	Fix $p\in\Teich(A)$ with $\lambda(p)=t$, and let $\tilde U=i_*^{-1}(p)$. By \ref{F3}, $\tilde U$ is the universal cover of $\Ch\setminus A_p$ via $\tau'\mapsto v'(\tau')$. Then $w=\lambda\circ f^*$ is the lift of $v'$ through the covering $V_t\colon\Ch\setminus V_t^{-1}(A_p)\to\Ch\setminus A_p$, and $f^*|_{\tilde U}$ is the lift of $w$ through $\lambda$. Both lifts are determined by their value at one point.
214	\end{lemma}
215	
216	\begin{proof}
217	By Lemma~\ref{lem:branch}, $V_t$ restricted as stated is a covering, since all its critical values lie in $A_p$. By \ref{F5} and Lemma~\ref{lem:fibreformula}, $w=\lambda\circ f^*$ is continuous on $\tilde U$ and satisfies $V_t\circ w=v'$; as $v'\notin A_p$, $w$ takes values in $\Ch\setminus V_t^{-1}(A_p)$. So $w$ is a lift of $v'$, and $f^*|_{\tilde U}$ is a lift of $w$ through $\lambda$ by definition. Since $\tilde U$ is connected, lifts are determined by their value at one point.
218	\end{proof}
219	
220	\section{\texorpdfstring{$\D_f$}{D\_f} is a smooth curve}
221	
222	\begin{lemma}\label{lem:smooth}
223	$\D_f$ is a one-dimensional complex submanifold of $\Teich(B)$. Hence its connected components are path components.
224	\end{lemma}
225	
226	\begin{proof}
227	The map $\Teich(B)\to\M_{0,5}$, $\tau'\mapsto(t',v')$, is a covering by \ref{F2} and Lemma~\ref{lem:free}, so $(t',v')$ are local coordinates. Let $\tau_1\in\D_f$ have coordinates $(t_1,v_1)$. Then $w(\tau_1)=\lambda(f^*\tau_1)=\lambda(i_*\tau_1)=t_1$, so $v_1=V_{t_1}(t_1)=v(t_1)$. Since $v_1\notin\{0,1,t_1,\infty\}$, Lemma~\ref{lem:branch} makes $V_{t_1}$ a local biholomorphism at $w=t_1$. By the implicit function theorem and continuity of $w$, near $\tau_1$ the function $w(t',v')$ is the holomorphic branch of $V_{t'}^{-1}(v')$ through $t_1$. Moreover $\lambda$ is injective near $i_*\tau_1=f^*\tau_1$. So near $\tau_1$ the condition $f^*\tau'=i_*\tau'$ is equivalent to $w(t',v')=t'$, i.e.\ to $v'=V_{t'}(t')=v(t')$, which defines a holomorphic graph.
228	\end{proof}
229	
230	\section{The linking criterion}
231	
232	\begin{proposition}\label{prop:linking}
233	Let $T\in\PMod(S^2,B)$ satisfy $\Psi\circ T=\Psi$, so that $T^{\pm1}(\D_f)=\D_f$. Let $g\in\Gamma(2)S$ have no fixed point in $\HH$. Let $\tau\in\D_f$ with $p_0=i_*\tau$, and let $D_0$ be its component. Suppose that for each $m\ne0$ there is a path $\sigma'_m$ in the fibre $i_*^{-1}(p_0)$ from $\tau$ to $T^m\tau$ such that the loop $f^*\circ\sigma'_m$ has nonzero winding number about $g(p_0)$. Then $T^m D_0\ne D_0$ for every $m\ne0$.
234	\end{proposition}
235	
236	\begin{proof}
237	Let $X_g=\HH\times\HH\setminus\Gamma_g$. The map $(p,q)\mapsto\bigl(p,(q-\Rea g(p))/\Img g(p)\bigr)$ identifies $X_g$ with $\HH\times(\HH\setminus\{i\})$, and is an orientation-preserving affine map on each fibre $\{p\}\times\HH$. So $H_1(X_g)\cong\mathbb Z$, and the class of a loop in $\{p\}\times\HH$ is its winding number about $g(p)$. By $(\star)$, $\Psi(\Teich(B))\subset X_g$, and since $g$ has no fixed point, $\Delta\subset X_g$.
238	
239	Suppose $T^mD_0=D_0$. By Lemma~\ref{lem:smooth} there is a path $\sigma\subset D_0$ from $\tau$ to $T^m\tau$. Since $\Teich(B)$ is contractible \ref{F2}, $\sigma\simeq\sigma'_m$ rel endpoints. Applying $\Psi$, the loops $\Psi\sigma$ and $\Psi\sigma'_m$ (they are loops because $\Psi(T^m\tau)=\Psi(\tau)$) are homotopic in $X_g$. But $\Psi\sigma\subset\Delta$, which is contractible, so $\Psi\sigma$ is null-homologous in $X_g$, whereas $\Psi\sigma'_m=(p_0,f^*\sigma'_m)$ has nonzero class. This is a contradiction.
240	\end{proof}
241	
242	\section{The computation at \texorpdfstring{$t_0=\tfrac14$}{t0=1/4}}\label{sec:comp}
243	
244	From now on $f=f_{1/4}$ and $V=V_{1/4}$. Since $(w-1)^2-\tfrac14=(w-\tfrac12)(w-\tfrac32)$,
245	\[V(w)=-\frac{(w-\frac12)^2(w-\frac32)^2}{4w(w-1)(w-\frac34)} .\]
246	
247	\paragraph{Deck group.} Put $g_0(w)=\dfrac{w-3/4}{w-1}$, $g_2(w)=\dfrac3{4w}$ and $g_3=g_0g_2=g_2g_0=\dfrac{3(w-1)}{4(w-3/4)}$; $g_0$ and $g_2$ are commuting involutions. Direct substitution gives $V\circ g_0=V\circ g_2=V$:
248	\begin{itemize}[nosep]
249	\item under $g_2$: $w-\tfrac12\mapsto-(w-\tfrac32)/(2w)$, $w-\tfrac32\mapsto-3(w-\tfrac12)/(2w)$, and $4w(w-1)(w-\tfrac34)\mapsto 9(w-\tfrac34)(w-1)/(4w^3)$;
250	\item under $g_0$: $w-\tfrac12\mapsto(w-\tfrac12)/(2(w-1))$, $w-\tfrac32\mapsto-(w-\tfrac32)/(2(w-1))$, and the denominator becomes $w(w-\tfrac34)/(4(w-1)^3)$.
251	\end{itemize}
252	So $V$ is Galois with Klein four deck group $\{\mathrm{id},g_0,g_2,g_3\}$. Its $6$ critical points are the fixed points of $g_0,g_2,g_3$:
253	$\tfrac12,\tfrac32$, which lie over $0$; $\pm\tfrac{\sqrt3}2$, which lie over $1$; and $P,\bar P=\tfrac34\pm\tfrac{\sqrt3}4 i$, which lie over $\tfrac14$. The critical values are therefore $0,1,\tfrac14\in A$.
254	
255	\paragraph{Real locus.} $V$ has real coefficients, so $V(w)\in\Rh$ iff $V(\bar w)=V(w)$ iff $\bar w=h(w)$ for some deck map $h$:
256	$h=\mathrm{id}$ gives $\Rh$; $h=g_0$ gives the circle $C_1\colon|w-1|=\tfrac12$; $h=g_2$ gives $C_2\colon|w|=\tfrac{\sqrt3}2$; and $h=g_3$ gives $|w-\tfrac34|^2=-\tfrac3{16}$, which is empty. Moreover $C_1\cap C_2=\{P,\bar P\}$.
257	
258	\paragraph{Faces.} All critical values of $V$ are real. So $V$ restricted to $\Ch\setminus V^{-1}(\Rh)$ is a covering of the two open half-planes, and each complementary component (face) maps homeomorphically onto one half-plane. Adjacent faces map to opposite half-planes, because $V$ is a local homeomorphism along each edge. We need four faces, all inside $C_2$ and hence avoiding $w=1$:
259	\begin{gather*}
260	L_2=\{\Img w<0,\ |w|<\tfrac{\sqrt3}2,\ |w-1|>\tfrac12\},\qquad U_2=\overline{L_2}\ \text{(complex conjugate)},\\
261	U_{12}=\{\Img w>0,\ |w|<\tfrac{\sqrt3}2,\ |w-1|<\tfrac12\},\qquad L_{12}=\overline{U_{12}}.
262	\end{gather*}
263	
264	\paragraph{Boundary values.} The vertices of the graph $V^{-1}(\Rh)$ are the points of $V^{-1}(\{0,1,\tfrac14,\infty\})=\{\tfrac12,\tfrac32,\pm\tfrac{\sqrt3}2,P,\bar P,0,1,\tfrac34,\infty\}$. Each edge contains no vertex except at its ends, so it maps homeomorphically onto the arc of $\Rh$ between the images of its ends that avoids the other marked values.
265	\begin{itemize}[nosep]
266	\item On $(-\tfrac{\sqrt3}2,0)$, $V$ increases from $1$ to $+\infty$: here $V\approx-3/(16w)$ near $0$, and $V(-\tfrac{\sqrt3}2)=1$.
267	\item On $(0,\tfrac12)$, $V$ increases from $-\infty$ to $0$, with $V(\tfrac14)=v$.
268	\item On $(\tfrac12,\tfrac34)$, $V$ decreases from $0$ to $-\infty$, with $V(\tfrac23)=v$, since $\tfrac23=g_0(\tfrac14)$.
269	\item The $C_1$-arcs from $\tfrac12$ to $P$ and from $\tfrac12$ to $\bar P$ map onto $(0,\tfrac14)$: the alternative arc of $\Rh$ from $0$ to $\tfrac14$ would pass through $\infty$ and $1$, whose preimages $0,1,\tfrac34,\pm\tfrac{\sqrt3}2$ are not on these arcs.
270	\item The $C_2$-arcs from $P$ to $-\tfrac{\sqrt3}2$ (outside $C_1$) and from $P$ to $\tfrac{\sqrt3}2$ (inside $C_1$), and their conjugates, map onto $(\tfrac14,1)$; the segment $(\tfrac34,\tfrac{\sqrt3}2)$ maps onto $(1,\infty)$.
271	\item $V'(\tfrac14)>0$ and $V$ is real on $\mathbb R$, so $U_2$, which lies just above $\tfrac14$, maps to the upper half-plane.
272	\end{itemize}
273	Since $U_2$ is adjacent to $L_2$ across $(-\tfrac{\sqrt3}2,0)$ and to $U_{12}$ across the $C_1$-arc from $\tfrac12$ to $P$, and $U_{12}$ is adjacent to $L_{12}$ across $(\tfrac12,\tfrac34)$, it follows that $U_2$ and $L_{12}$ map to the upper half-plane, and $L_2$ and $U_{12}$ to the lower.
274	
275	\paragraph{Lift of $\alpha$.} Let $\beta$ be the lift of $\alpha$ through $V$ starting at $w=\tfrac14$, which lies over $v$. The four sub-arcs of $\alpha$ between consecutive points of $\alpha\cap\Rh$ each lie in one open half-plane, and on each face the inverse of $V$ is a homeomorphism onto the closure of that face; at the crossing points $V$ is a local biholomorphism, real on $\mathbb R$.
276	\begin{enumerate}[label=\textup{\arabic*.},nosep]
277	\item $\alpha$ leaves $v$ downward. Since $V'(\tfrac14)>0$, $\beta$ enters $L_2$. On $\partial L_2$ the preimage of $(1,\infty)$ is $(-\tfrac{\sqrt3}2,0)$, where $V$ is increasing, so $\beta$ crosses $\mathbb R$ there, upward, into $U_2$.
278	\item On $\partial U_2$ the preimage of $(0,\tfrac14)$ is the $C_1$-arc from $\tfrac12$ to $P$. $\beta$ crosses it into $U_{12}$.
279	\item On $\partial U_{12}$ the preimage of $(v,0)$ is $(\tfrac12,\tfrac23)$, where $V$ is decreasing. $\beta$ crosses it downward into $L_{12}$.
280	\item The only preimage of $\infty$ in $\overline{L_{12}}$ is $\tfrac34$ (the poles $0$ and $1$ lie outside $C_1$ and $C_2$ respectively). So $\beta$ ends at $w=\tfrac34=1-t_0$.
281	\end{enumerate}
282	In particular only the crossing pattern of $\alpha$ was used, not the concrete realisation. The arc $\beta$ lies in the disc $|w|<\tfrac{\sqrt3}2$, which avoids $1$, and avoids $0$. It meets $\mathbb R$ only at $\tfrac14$, at one point of the negative real axis (crossed upward), at one point of $(\tfrac12,\tfrac23)$ (crossed downward), and at $\tfrac34$, which it reaches from below. Following the argument of $w$ along $\beta$ followed by the segment $[\tfrac34,\tfrac14]$, it decreases by $2\pi$. So this closed loop has winding number $-1$ about $0$, and since the homotopy class of a loop in a punctured disc is determined by its winding number, in $\mathbb C\setminus\{0,1\}$
283	\begin{equation}\label{eq:beta}
284	\beta\simeq(\text{clockwise loop about }0\text{ based at }\tfrac14)\cdot[\tfrac14,\tfrac34]\qquad\text{rel endpoints}.
285	\end{equation}
286	
287	\paragraph{Lift through $\lambda$.} The clockwise loop about $0$ is homotopic to: go from $\tfrac14$ to $\varepsilon$ along $\mathbb R$, around the small clockwise circle $|w|=\varepsilon$, and back. By \ref{F1} its $\lambda$-lift from $p_0=iy_0$ goes up the imaginary axis, then decreases $\Rea\tau$ by $2$ (as $\lambda\approx16e^{i\pi\tau}$ for large $\Img\tau$), and comes back down; it ends at $p_0-2$. By $\lambda(-1/\tau)=1-\lambda(\tau)$ and $\lambda(\tau-2)=\lambda(\tau)$, the segment $[\tfrac14,\tfrac34]$ then lifts to the vertical segment from $p_0-2$ to $-2+i/y_0$. So the endpoint of the $\lambda$-lift of $\beta$ from $p_0$ is
288	\[q^*=g(p_0),\qquad g=T^{-2}S=\begin{pmatrix}-2&-1\\1&0\end{pmatrix}\in\Gamma(2)S,\qquad \operatorname{tr}g=-2,\]
289	where $T$ here denotes $\tau\mapsto\tau+1$. So $g$ is parabolic and has no fixed point in $\HH$.
290	
291	\begin{remark}[orientation conventions]
292	Had the winding of $\beta$ about $0$ been $+1$ instead of $-1$ (e.g.\ under the opposite orientation convention), the same computation would give $g=T^{2}S=\begin{pmatrix}2&-1\\1&0\end{pmatrix}$, of trace $2$, again parabolic. More generally $T^{2k}S$ has trace $2k$ and is fixed-point-free on $\HH$ for every $k\ne0$; only the fact that the winding is nonzero matters.
293	\end{remark}
294	
295	\section{Proof of Theorem~\ref{thm:main}(a)}\label{sec:proofa}
296	
297	\paragraph{$\alpha$ is simple and $\gamma$ is as claimed.} In the concrete realisation, the lower semicircle from $v$ to $2$ has centre $\approx0.870$ and radius $\approx1.130$; the small lower semicircle over $[-\tfrac18,\tfrac18]$ lies within distance $0.995$ of that centre, so strictly inside it. The upper semicircle over $[\tfrac18,2]$ has real parts in $[\tfrac18,2]$, so it misses the vertical ray at $\Rea z=-\tfrac18$. The arc meets $\Rh$ only at $v,2,\tfrac18,-\tfrac18,\infty$, with $2\in(1,\infty)$, $\tfrac18\in(0,\tfrac14)$ and $-\tfrac18\in(v,0)$, crossing transversally in the required directions. So $\alpha$ is simple, has the crossing pattern, and meets $B$ only at its ends. For any simple arc $\alpha$ with the crossing pattern, $\gamma=\partial N(\alpha)$ bounds a disc containing exactly $v,a_1$, because $\alpha$ is simple with interior in $S^2\setminus B$; and the lifting argument of \S\ref{sec:comp} used only the crossing pattern. Everything below therefore applies to any such arc.
298	
299	\paragraph{$T_\gamma$ is a point push.} Let $\ell$ be the lasso: follow $\alpha$ to near $a_1$, go once around $a_1$, and return. A regular neighbourhood of $\ell$ is an annulus. One of its boundary curves bounds a disc containing only $a_1$ (so the twist about it is trivial), and the other is $\gamma$. So by \ref{F4}, $\Push(\ell)=T_\gamma^{\pm1}$. In particular $T_\gamma$ maps to $1$ in $\PMod(S^2,A)$, so $i_*\circ T_\gamma=i_*$.
300	
301	\paragraph{$T_\gamma$ preserves $\D_f$.} Work in the fibre $i_*^{-1}(p_0)$ through $\tau_0$; here $A_{p_0}=\{0,\infty,1,\tfrac14\}$, $v'(\tau_0)=v$, $w(\tau_0)=\lambda(f^*\tau_0)=\tfrac14$ and $f^*\tau_0=p_0$, because $\tau_0\in\D_f$.
302	\begin{itemize}[nosep]
303	\item By \ref{F3}, there is a path $\sigma'$ from $\tau_0$ to $T_\gamma^{\pm1}\tau_0$ which projects to $\ell$ under $v'$.
304	\item Truncate $\alpha$ to $\alpha'$, stopping just before $a_1$. By the fibre lemma~\ref{lem:fibre}, $w\circ\sigma'$ is the $V$-lift of $\ell$ starting at $\tfrac14$, which is $\beta'\cdot c\cdot\beta'^{-1}$. Here $\beta'$ is the corresponding truncation of $\beta$, and $c$ is a small loop about $\tfrac34$; this uses that $\tfrac34$ is a simple preimage of $\infty$.
305	\item Since $\tfrac34\notin\{0,1\}$, $c$ is null-homotopic in $\mathbb C\setminus\{0,1\}$. So its $\lambda$-lift is a small closed loop $\tilde c$ about $q^*$ (recall $\lambda(q^*)=\tfrac34$ and $\lambda$ is a local biholomorphism), and $f^*\sigma'=\tilde\beta'\cdot\tilde c\cdot\tilde\beta'^{-1}$ is closed, where $\tilde\beta'$ is the $\lambda$-lift of $\beta'$ from $p_0$.
306	\item Hence $f^*(T_\gamma^{\pm1}\tau_0)=f^*(\tau_0)$. By Lemma~\ref{lem:lift}, $[\tilde T]^{\pm1}$ fixes the point $f^*\tau_0$, so $[\tilde T]=1$ by Lemma~\ref{lem:free}.
307	\item Therefore $f^*\circ T_\gamma=f^*$ on all of $\Teich(B)$. Together with $i_*\circ T_\gamma=i_*$ this gives $\Psi\circ T_\gamma=\Psi$, and so $T_\gamma^{\pm1}(\D_f)=\D_f$.
308	\end{itemize}
309	
310	\paragraph{Infinite orbits.} Fix $m\ne0$, and let $\sigma'_m$ be the path in the fibre from $\tau_0$ to $T_\gamma^m\tau_0$ lying over the loop $\ell^{\pm m}$ (\ref{F3}). As above, $f^*\sigma'_m=\tilde\beta'\,\tilde c^{\,\pm m}\,\tilde\beta'^{-1}$. This loop lies in $\HH\setminus\{g(p_0)\}$ by $(\star)$, and its winding number about $q^*=g(p_0)$ is $\pm m\ne0$, because $\tilde c$ winds once about $q^*$ (it is the image of a small circle about $\tfrac34$ under a local inverse of $\lambda$). So the class of $\Psi\circ\sigma'_m$ in $H_1(X_g)\cong\mathbb Z$ is $\pm m$, and Proposition~\ref{prop:linking} (with $T=T_\gamma$, $\tau=\tau_0$) gives $T_\gamma^mD_0\ne D_0$ for the component $D_0$ of $\tau_0$.
311	
312	Now let $\tau_1\in\D_f$ be arbitrary and $D_1$ its component. Choose a path $\rho$ from $\tau_0$ to $\tau_1$. Then $\rho^{-1}\cdot\sigma'_m\cdot T_\gamma^m\rho$ is a path from $\tau_1$ to $T_\gamma^m\tau_1$. Since $\Psi\circ T_\gamma^m=\Psi$, its $\Psi$-image is the conjugate loop $(\Psi\rho)^{-1}(\Psi\sigma'_m)(\Psi\rho)$, which lies in $X_g$ and has class $\pm m$. Suppose $T_\gamma^mD_1=D_1$, and let $\sigma\subset D_1$ be a path from $\tau_1$ to $T_\gamma^m\tau_1$ (Lemma~\ref{lem:smooth}). Contractibility of $\Teich(B)$ makes the two paths homotopic rel endpoints, so their $\Psi$-images are homotopic in $X_g$. But $\Psi\sigma\subset\Delta$, which is contractible, so its class is $0$, a contradiction. This is the argument of Proposition~\ref{prop:linking} with the base point moved to $\tau_1$. Hence $T_\gamma^mD_1\ne D_1$ for every component $D_1$ and every $m\ne0$: every orbit of $\langle T_\gamma\rangle$ on $\pi_0(\D_f)$ is infinite. This proves Theorem~\ref{thm:main}(a). \qed
313	
314	\begin{remark}[a direct topological proof that the lift is trivial]
315	The identity $f^*\circ T_\gamma=f^*$ can also be seen without the fibre computation. Put $s=1/z-\tfrac{11}4$. Then $f=v+s^2/6$, since $v+\tfrac16(1/z-\tfrac{11}4)^2=v+\tfrac{121}{96}-\tfrac{11}{12z}+\tfrac1{6z^2}$ and $v+\tfrac{121}{96}=1$. The critical points are $s=0$ ($z=c_2$, over $v$) and $s=\infty$ ($z=0=a_0$, over $a_1=\infty$). In this coordinate $s(a_0)=\infty$, $s(a_1)=-\tfrac{11}4$, $s(a_2)=-\tfrac74$, $s(a_3)=\tfrac54$, and the positive numbers $\tfrac54<\tfrac74<\tfrac{11}4$ satisfy $v+s^2/6=0,\tfrac14,1$ respectively.
316	
317	Put $Y=f-v=s^2/6$. The arc $\alpha$ meets $\Rh$, apart from its endpoints, only at $x_1,x_2,x_3>v$, i.e.\ at positive $Y$. So the interior of $\alpha$ lies in $\mathbb C\setminus(-\infty,0]$ in the $Y$-coordinate, where $s=\sqrt{6Y}$ has a branch with $\Rea s>0$. Hence $f^{-1}(\alpha)=\alpha_+\cup(-\alpha_+)$ with $\alpha_+\subset\{\Rea s>0\}$ a simple arc from $s=0$ to $s=\infty$, and $J=f^{-1}(\alpha)$ is a Jordan curve through $0$ and $\infty$. The involution $s\mapsto-s$ preserves $J$ and exchanges its two complementary discs $\Omega,\Omega'$: near its fixed point $0\in J$ it is a rotation by $\pi$ which exchanges the two local sides of $J$.
318	
319	$J$ meets the positive real $s$-axis only in $\alpha_+$, at the three transversal crossings $s_i=\sqrt{6(x_i-v)}$, and $x_3<0<x_2<\tfrac14<1<x_1$ gives $s_3<\tfrac54<s_2<\tfrac74<\tfrac{11}4<s_1$. So $\tfrac54$ and $\tfrac74$ lie on opposite sides of $J$, and $\tfrac74,\tfrac{11}4$ on the same side. Say $\tfrac54\in\Omega$; then $\tfrac74,\tfrac{11}4\in\Omega'$, so $-\tfrac74,-\tfrac{11}4\in\Omega$. Hence $a_1,a_2,a_3\in\Omega$ and $a_0\in J$. Now $f^{-1}(N(\alpha))$ is a regular neighbourhood of $J$, and the collars $R_1,R_2$ of Lemma~\ref{lem:lift} are parallel to its two boundary curves $\gamma_1\subset\Omega$, $\gamma_2\subset\Omega'$. The curve $\gamma_1$ separates $\{a_1,a_2,a_3\}$ from $\{a_0\}$, so it is peripheral in $(S^2,A)$, and $\gamma_2$ bounds a disc in $\Omega'$ containing no point of $A$. Twists about such curves are trivial in $\PMod(S^2,A)$, so $[\tilde T]=1$, i.e.\ $f^*\circ T_\gamma=f^*$.
320	\end{remark}
